    public function getSourceContext(): Source
    {
        return new Source("{% extends 'base.html.twig' %}
{% block title %}Réinitialiser votre mot de passe{% endblock %}
{% block body %}
<div class=\"min-h-screen bg-cover bg-center flex items-center justify-center\" style=\"background-image: url('{{ asset(\"assets/images/login_background.jpg\") }}')\">
  <div class=\"bg-white shadow-lg rounded-lg p-8 max-w-md w-full opacity-75\">
    <h1 class=\"text-2xl font-bold text-center text-gray-800 mb-6\">
      Réinitialiser votre mot de passe
    </h1>
    <div class=\"mb-4\">
      {{ form_start(resetForm, {'attr': {'class': 'gap-4 flex flex-col'}}) }}

          {{ form_widget(resetForm.plainPassword, { 'attr' : {'class' : 'flex flex-col gap-4'}}) }}

          <div class=\"error-message\"> 
            {{ form_errors(resetForm.plainPassword, {'attr': {'class': 'text-red-500 text-sm mt-1'}}) }}
          </div>
          <div>
            <small>
              Choisissez un mot de passe fort et unique pour votre compte.
            </small>
          </div>
        <button type=\"submit\" class=\"w-full bg-blue-600 text-white py-2 px-4 rounded-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2\">
          Réinitialiser le mot de passe
        </button>
      {{ form_end(resetForm) }}

      <div class=\"mt-4 text-center\">
        <a href=\"{{ path('app_login') }}\" class=\"text-sm text-blue-600 hover:text-blue-500\">
          Retour à la page de connexion
        </a>
      </div>
    </div>
  </div>
</div>
{% endblock %}
", "reset_password/reset.html.twig", "/var/www/html/templates/reset_password/reset.html.twig");
